registry.register('JwtAuth', ()=> new JwtAuthPolicy())
registry.register('RBAC', ()=> new RoleBasedPolicy())
registry.register('Quota', ()=> new QuotaPolicy())
registry.register('Transform', ()=> new JsonTransformPolicy())
const chain = new PolicyChain([
  registry.resolve('JwtAuth')!,
  registry.resolve('RBAC')!,
  registry.resolve('Quota')!,
  registry.resolve('Transform')!
])
```

